import sympy

def build_instance(rng):
    constant_term = rng.randint(-10, 10)
    x = sympy.symbols('x')
    equation = x ** 3 - 3 * x ** 2 + 2 * x - constant_term
    roots = sympy.solve(equation, x)
    answer = len([root for root in roots if root.is_real is True])
    check = sum((1 for root in roots if root.is_real is True))
    parameters = {'constant_term': constant_term}
    return (parameters, answer, check)



