    right_x = rng.randint(2, 10)
    slope = rng.randint(-10, 10)
    y_intercept = rng.randint(-10, 10)
    constant = rng.randint(-10, 10)
    x = sympy.symbols('x', integer=True)
    inequality = slope * x + y_intercept <= constant
    solution = sympy.solve_univariate_inequality(inequality, x, relational=False)
    answer = [i for i in range(left_x, right_x + 1) if i in solution]
    count = len(answer)
    answer_text = str(count)
    check = [i for i in range(left_x, right_x + 1) if slope * i + y_intercept <= constant]
    check_text = str(len(check))
    answer = answer_text
    check = check_text
    parameters = {'left_x': left_x, 'right_x': right_x, 'slope': slope, 'y_intercept': y_intercept, 'constant': constant}
    return (parameters, answer, check)



